def find_corners(lines):
    """
    Finds all corners ('+') in the given lines of ASCII art.

    :param lines: List of strings representing the ASCII art picture.
    :return: List of tuples (x, y) representing the coordinates of corners.
    """
    corners = []
    for y, line in enumerate(lines):
        for x, char in enumerate(line):
            if char == '+':
                corners.append((x, y))
    return corners

